"""Self-contained interactive research/build report from final NBT previews."""
from pathlib import Path
import sys,json,base64,io,hashlib,html,collections
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];run=sys.argv[1];OUT=Path(sys.argv[2]);world=Path(sys.argv[3]);R=ROOT/'runs'/run;D=ROOT/'review/previews'/run
sp=json.loads((R/'spec.json').read_text());qa=json.loads((R/'audit.json').read_text());wc=json.loads((R/'world_check.json').read_text());rc=json.loads((R/'random_check.json').read_text());images={};records=[]
for group in ['overview','streets']+[f'B{i:02d}'for i in range(1,19)]+['creek']:
 rs=json.loads((D/(group+'_report.json')).read_text());records+=rs
 for rec in rs:
  p=D/rec['image'];im=Image.open(p);assert im.info['source_nbt_sha256']==sp['source_nbt_sha256'];assert hashlib.sha256(p.read_bytes()).hexdigest()==rec['sha256']
  buf=io.BytesIO();im.convert('RGB').save(buf,format='WEBP',quality=88,method=6);images[p.stem]='data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
images['exploded']='data:image/svg+xml;base64,'+base64.b64encode((D/'exploded.svg').read_bytes()).decode();(D/'all_views.json').write_text(json.dumps(records,indent=2))
used=set()
def img(key,id=''):
 used.add(key);return f'<img class="zoom" data-img="{key}" '+(f'id="{id}" 'if id else'')+f'src="{images[key]}" alt="{key}" loading="lazy">'
def card(key,title,caption):return '<figure>'+img(key)+f'<figcaption><b>{title}</b><p>{caption}</p></figcaption></figure>'
def download(p,mime,label):return f'<a class="download" download="{p.name}" href="data:{mime};base64,'+base64.b64encode(p.read_bytes()).decode()+f'">{label} ↓</a>'
def controls(id,items,attr='view'):return f'<div class="controls" id="{id}">'+''.join(f'<button data-{attr}="{k}">{t}</button>'for k,t in items)+'</div>'
styles='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f5f2e9;color:#283c34;font:16px/1.7 system-ui,-apple-system,"Noto Sans CJK SC","Microsoft YaHei",sans-serif}header{border-bottom:1px solid #d3d8ca;display:flex;justify-content:space-between;align-items:center;padding:18px max(24px,calc((100vw - 1220px)/2));gap:20px}header b{letter-spacing:.13em;font-size:13px}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:inherit;text-underline-offset:4px}nav a{text-decoration:none;font-size:14px}main{max-width:1220px;margin:auto;padding:40px 24px}section{padding:44px 0;border-bottom:1px solid #d3d8ca;scroll-margin-top:18px}.kicker{font-size:12px;letter-spacing:.16em;color:#647969;text-transform:uppercase}.title{display:grid;grid-template-columns:1.1fr 1fr;align-items:end;gap:40px;margin-bottom:30px}h1{font-family:"Noto Serif CJK SC","Songti SC",serif;font-size:clamp(46px,6vw,78px);font-weight:500;line-height:1.23;margin:14px 0}h2{font-size:29px;font-weight:600;letter-spacing:-.03em;margin:8px 0 20px}h3{margin:0 0 10px;font-size:23px}.lead{color:#52655b;font-size:18px}.badge{display:inline-block;border:1px solid #a9b9aa;border-radius:30px;padding:3px 12px;font-size:12px;margin:0 5px 6px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.stats div{border-left:2px solid #8ba08a;padding:6px 16px}.stats strong{display:block;font-size:27px}.stats span{font-size:13px;color:#617265}figure{margin:0;background:#e8e7dd;border:1px solid #d0d5c6;border-radius:6px;overflow:hidden}figure img{display:block;width:100%;height:auto;aspect-ratio:1.4;object-fit:contain;cursor:zoom-in}figcaption{padding:16px 19px}figcaption p{margin:4px 0 0;font-size:13px;color:#637164}.controls{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0 21px}button,.download,select{border:1px solid #b8c5b4;color:#304b3b;background:#faf9f3;border-radius:5px;padding:9px 14px;font:inherit;font-size:13px;cursor:pointer;text-decoration:none}button:hover,button.active,.download:hover{background:#345a44;color:white;border-color:#345a44}button:focus-visible,a:focus-visible,select:focus-visible{outline:3px solid #c47b55;outline-offset:3px}.note{border-left:3px solid #b4885d;background:#eceadd;padding:16px 20px;margin:22px 0;font-size:14px}.map-wrap{border:1px solid #cbd4c6;border-radius:6px;overflow:hidden;background:#dce4ca}.map-wrap svg{width:100%;display:block}.lot{cursor:pointer}.lot rect{fill:#f5ecda;stroke:#6d7c65;stroke-width:.5}.lot:hover rect,.lot.active rect{fill:#dbad78;stroke:#6f4d2a;stroke-width:1}.lot text{font-size:3px;fill:#314232;font-weight:700;pointer-events:none}.building-layout{display:grid;grid-template-columns:1fr 2fr;gap:28px;margin-top:28px}.building-meta{background:#e7ecde;border-radius:6px;padding:24px}.building-meta p{font-size:14px}.building-meta code{display:block;overflow-wrap:anywhere;font-size:13px;background:#faf9f2;padding:12px;margin:12px 0}.build-selector{max-height:320px;overflow-y:auto}.building-name{width:100%;text-align:left;display:block;margin:0 0 6px}.small{font-size:13px;color:#66786a}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{border-bottom:1px solid #d0d9c9;padding:12px 10px;text-align:left;font-size:14px}th{font-weight:600;background:#e8eddf}details{margin-top:22px;background:#edf0e4;padding:15px 20px;border-radius:5px}summary{cursor:pointer;font-weight:600}.img-download{display:inline-block;font-size:12px;margin-top:5px}footer{padding:36px 0;color:#798576;font-size:12px}dialog{max-width:95vw;max-height:95vh;border:0;border-radius:8px;padding:10px;background:#f5f2e9}dialog img{display:block;max-width:90vw;max-height:82vh;object-fit:contain}dialog::backdrop{background:#17231ad9}dialog button{float:right;margin:8px}#view-caption{font-size:13px;color:#566d5c}#map-hint{font-size:13px} .two-col{columns:2;column-gap:32px}.hero-figure img{max-height:720px}@media(max-width:740px){header{align-items:flex-start;padding:16px 20px}nav{gap:10px}.title,.grid,.building-layout{grid-template-columns:1fr}.title{gap:10px}.stats{grid-template-columns:1fr 1fr}main{padding:20px 16px}section{padding:32px 0}h2{font-size:25px}.two-col{columns:1}.build-selector{max-height:180px}button{padding:10px 12px}.building-meta{padding:18px}}'''
p=['<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>木漏日町 · 18 栋日式小街区</title><style>'+styles+'</style></head><body><header><b>KOMOREBI / 09</b><nav><a href="#walk">街景</a><a href="#map">十八栋</a><a href="#green">溪岸与草花</a><a href="#download">地图</a></nav></header><main>']
p.append('<section><div class="title"><div><div class="kicker">HAF 0.4 / '+run+' / 2026.10.30</div><h1>木漏日町<br>转过街角，<br>就是溪边。</h1><span class="badge">18 栋 · 老式日式街区</span><span class="badge">一层小店 × 两层住商楼</span></div><div><p class="lead">从有灯、有陈列的店口走进窄巷，再沿着草花和树荫来到小溪旁。让街区在人物视角里也有可看的层次。</p><p class="small">延续已认可的 Machiya08 门面与屋顶方法；这次把用途、楼层高度、屋脊方向和建筑退距分开组织。</p></div></div><figure class="hero-figure">'+img('day_SE','hero-img')+'<figcaption><b id="hero-caption">整街鸟瞰 · 日景</b><p>最终建筑文件离线预览，可点击放大；不是 Minecraft 客户端截图。</p></figcaption></figure>'+controls('hero-controls',[('day_SE','整街日景'),('night_SE','整街夜景'),('main_west','走进商店街'),('creek_bend','站在桥上'),('creek_walk','沿溪散步')])+'<div class="stats"><div><strong>18 栋</strong><span>4 大町屋 / 6 紧凑两层 / 8 单层</span></div><div><strong>2 座桥</strong><span>石桥接主街 · 木桥接安静小路</span></div><div><strong>'+str(len(sp['groundcover']))+' 株</strong><span>地面草花；按簇、树荫和墙根分布</span></div><div><strong>'+str(len(sp['trees']))+' 组</strong><span>高低树冠 · 少量樱色点景</span></div></div></section>')
p.append('<section id="walk"><div class="kicker">01 / Walk the block</div><h2>先从街上看。</h2><div class="grid">'+card('main_west','商店街 · 两侧店口','一层低檐与两层窗组交替，开放窗台、暖帘和候位凳沿街出现。')+card('quiet_lane','转入石铺小街','房子间保留通路，门前的盆栽与墙根植物形成低处细节。')+card('wood_bridge','从小木桥走回街区','桥直接接上安静街道，水和植物位于两侧，不截断通行。')+card('cross_alley','横向巷道','连接两条街与各排房屋；楼间距比第一遍缩紧。')+'</div><details><summary>看夜景和其他街边位置</summary><div class="grid">'+card('main_west_night','商店街夜景','功能空间和通路设置灯；不依赖随机灭灯表现变化。')+card('quiet_lane_night','巷内夜景','店口暖帘、窗沿和街灯分层；真实游戏光照仍待实机。')+card('main_east','反向看商店街','避免只在单个拍摄方向里成立。')+card('green_pocket','巷侧小停留处','短坐凳与草花相邻，绿化保留局部空隙。')+'</div></details></section>')
# Geometry-based navigable diagram, not a claimed aerial survey.
map_parts=['<svg id="site-map" viewBox="0 0 164 112" role="img" aria-label="十八栋建筑导航，东侧为小溪"><rect width="164" height="112" fill="#dce4ca"/>']
for x,z in sp['route_cells']:map_parts.append(f'<rect x="{x}" y="{z}" width="1" height="1" fill="#c9c9b9"/>')
map_parts.append('<rect x="2" y="38" width="136" height="7" fill="#667169"/>')
for x,z in sp['water_cells']:map_parts.append(f'<rect x="{x}" y="{z}" width="1" height="1" fill="#8bb9b5"/>')
for x0,z0,x1,z1 in sp['bridges']:map_parts.append(f'<rect x="{x0}" y="{z0}" width="{x1-x0}" height="{z1-z0}" fill="#b69c71"/>')
for t in sp['trees']:map_parts.append(f'<circle cx="{t["x"]}" cy="{t["z"]}" r="{t["radius"]}" fill="#7f9d68" opacity=".75"/>')
for b in sp['buildings']:
 x0,_,z0,x1,_,z1=b['bounds'];label=b['id']
 map_parts.append(f'<g class="lot" data-building="{label}" tabindex="0" role="button" aria-label="{label} {b["name"]}"><rect x="{x0}" y="{z0}" width="{x1-x0}" height="{z1-z0}" rx=".8"/><text x="{(x0+x1)/2}" y="{(z0+z1)/2}" text-anchor="middle">{label}</text></g>')
map_parts.append('<text x="3" y="4" font-size="3" fill="#34513a">北 ↑ / -Z</text></svg>')
p.append('<section id="map"><div class="kicker">02 / Eighteen addresses</div><h2>每一栋，都能点开看。</h2><p id="map-hint">点击地图或下方编号，切换门面、室内、二层／细部与首层平面。地图是实际地块与水系的导航示意。</p><div class="map-wrap">'+''.join(map_parts)+'</div><div class="building-layout"><aside class="building-meta"><div class="kicker" id="building-id">B01</div><h3 id="building-title">日和小食</h3><p id="building-info"></p><code id="tp-command"></code><p class="small">进入地图后可复制上方传送指令。朝向按建筑入口设定。</p><label for="building-filter" class="small">筛选楼型</label><select id="building-filter"><option value="all">全部 18 栋</option><option value="machiya">大町屋 · 4 栋</option><option value="compact">紧凑两层 · 6 栋</option><option value="single">单层小店 · 8 栋</option></select><div class="build-selector" id="building-list">'+''.join(f'<button class="building-name" data-building="{b["id"]}" data-family="{b["family"]}">{b["id"]}　{b["name"]}</button>'for b in sp['buildings'])+'</div></aside><div>'+controls('building-views',[('front','临街门面'),('inside','首层室内'),('extra','二层 / 细部'),('plan','首层平面')],'mode')+'<figure>'+img('B01_front','building-img')+'<figcaption><b id="building-caption">B01 · 临街门面</b><p id="view-caption">近景保留真实屋顶与天花；平面单独切去上部。</p></figcaption></figure><a id="download-view" class="img-download" download="B01_front.webp" href="'+images['B01_front']+'">下载当前视图 ↓</a></div></div><details><summary>18 栋用途清单</summary><table><tr><th>编号</th><th>用途</th><th>层数</th><th>内部安排</th></tr>'+''.join('<tr><td>'+b['id']+'</td><td>'+b['name']+'</td><td>'+str(b['floors'])+'</td><td>'+('营业/起居、后厨/厨房、卫浴、上层床组与收纳'if b['floors']==2 else'用途陈列/工作或阅读/洗浴空间、服务点与小卫浴')+'</td></tr>'for b in sp['buildings'])+'</table></details></section>')
p.append('<section id="green"><div class="kicker">03 / Creekside & groundcover</div><h2>草地的细节，落到脚边。</h2><div class="grid">'+card('creek_bend','石桥上的溪景','微弯溪流沿街区东侧延伸，岸边混合草地与局部石收边。')+card('creek_cherry','树荫与临溪房屋','临溪立面补窗和薄格扇，树冠之间留出看水、看街屋的方向。')+card('grass_flowers','低草、草花与岸边细节','低草为主，花按簇出现，少量高草与阴处蕨类变化；不在主通路上撒植物。')+card('creek_walk','连续的沿溪小路','店铺之间的生活感延伸到房屋侧面和溪边。')+'</div><p>先固定道路、入口、家具和灯位，再在合法绿地里选树与草花。植物按稳定分组和种子变化；树下偏蕨类，开敞处偏草与花，墙根密一些，通路与门前保持清楚。</p><div class="note">本版 '+str(len(sp['trees']))+' 组树、'+str(len(sp['groundcover']))+' 株地面草花。seed 1145 重跑结构字节一致；换到 2718 产生 '+str(rc['changed_cells'])+' 格植物范围内变化，另一种子也通过入口和使用点检查。建筑布局为这次的固定原创设计。</div><details><summary>溪边夜景与整体关系</summary><div class="grid">'+card('creek_bend_night','溪边夜景','不把整条溪岸照成同亮度；路口和建筑仍是主要光源。')+card('creek_overview','小溪与街区的位置','两岸步道、两座桥和三排街屋的整体关系。')+'</div></details></section>')
p.append('<section id="inside"><div class="kicker">04 / Furnished spaces</div><h2>从可用的单栋，扩展到不同用途。</h2><div class="grid">'+card('B01_inside','町屋居酒屋','保留 M08 的吧台、桌席、后厨、楼道库存和墙画。')+card('B06_upper','住家上层','原版床、床头收纳、软席、衣柜与植物；楼梯接到实际楼板。')+card('B15_inside','小文库','壁面藏书、阅读桌、座位与借还侧台形成一组。')+card('B16_inside','木叶汤','浅浴池、干区、更衣储物和洗手盆；水体与通路分开。')+'</div><p>18 栋都有可进入的室内。本轮复用三类基础空间，并按用途调整陈列与家具，不把它们称作 18 套完全独立的通用生成器。沙发、普通座椅、杯瓶等为原版方块造型，真实床与储物使用原版实体。</p></section>')
p.append('<section><div class="kicker">05 / Same geometry</div><h2>平面、立面与剖面。</h2><div class="grid">'+card('top','完整屋顶俯视','垂直正交，场地 164 × 112 格；方位以模型坐标为准。')+card('plan_2','首层切层','剖去上部，查看每栋内部与街巷、水系的关系。')+card('plan_7','二层标高切层','y=7…10.99；单层建筑在此高度出现屋顶，不能误认为二层房间。')+card('exploded','楼板爆炸示意','仅显示实际木楼板，二层只取十栋两层楼；省略家具和屋面。')+'</div><details><summary>四向立面、关键街区剖切与其他日夜景</summary><div class="grid">'+''.join(card('elevation_'+k,t+'立面','同一比例的完整街区立面；前后建筑存在真实遮挡。')for k,t in [('south','南'),('east','东'),('north','北'),('west','西')])+card('section','中排建筑与巷道剖切','仅保留 z=44…73 范围的几何，查看两层空间与街区层次。')+''.join(card(k,t,'最终 NBT 同源离线预览。')for k,t in [('day_SW','西南日景'),('day_NW','西北日景'),('day_NE','东北日景'),('night_SW','西南夜景'),('night_NW','西北夜景'),('night_NE','东北夜景')])+'</div></details></section>')
p.append('<section id="download"><div class="kicker">06 / Enter the world</div><h2>走进去，再看它有没有生活感。</h2><p>'+download(world,'application/zip','下载 Java 1.21.1 地图')+' '+download(R/'Komorebi09.nbt','application/octet-stream','结构 NBT')+'</p><p>'+download(R/'design_contract.json','application/json','布局与绿化数据')+' '+download(R/'design_prompts.txt','text/plain','设计关键词')+'</p><ol><li>解压地图包，将 <b>Komorebi09_1.21.1</b> 文件夹放进 Minecraft 的 <code>saves</code>。</li><li>使用 Java 1.21.1、创造模式，无必需模组。出生点 <code>-15 65 -13</code> 位于主街。</li><li>先走商店街 → 横巷 → 木桥 → 沿溪小路，再逐栋进入查看。可用 <code>/time set night</code> 看夜景。</li></ol><div class="note">世界默认暂停昼夜、天气与随机刻更新，以保存植物和建筑展示状态。NBT 为稀疏结构，粘贴时须先清空完整范围；直接使用地图包更省事。</div><table><tr><th>离线检查</th><th>结果与边界</th></tr><tr><td>入口 / 使用点</td><td>18 / 18 栋入口、285 个使用点通过；十条楼梯通路通过近似人物碰撞检查。</td></tr><tr><td>水与植物</td><td>溪流底部与侧壁围合、草花承托、树叶持久状态和通路避让已检查。</td></tr><tr><td>世界回读</td><td>'+f'{wc["checked_cells"]:,}'+' 格检查，0 差异；335 个方块实体与 12 幅画实体载荷一致。</td></tr><tr><td>预览</td><td>'+str(len(records))+' 张当前 PNG 对应最终结构；网页内可放大和逐栋查看。</td></tr><tr><td>仍待确认</td><td>Minecraft 实机碰撞、交互、光照和这一版整体审美。</td></tr></table><details><summary>版本、研究范围与表现边界</summary><p>J01 建立 18 栋、溪岸与草花；J02 收紧楼间距并保留溪边绿带；'+run+' 补临溪和巷侧窗组。既有 Machiya08 M08 获认可，本次作为四栋大町屋的基础；旧整镇内饰的历史否定记录不因此自动关闭。</p><p>沿用上一轮 Freedom #80 公开静帧与 #104 局部展示片段的观察记录，本轮没有新增观看视频。具体地块、房间和绿化属于原创适配，不宣称现实测绘或完整教程复刻。</p><p>原版模型与材质离线绘制，床、旗帜、告示牌和水的部分表现简化；概览与街景降低纹理采样，近景使用更高采样。没有用生成意向图替代实际地图。局部建筑图只裁出对应建筑附近，保留它的完整墙体、屋顶与天花。</p><p>所有功能空间设置灯具，但原版冷暖材质不等于彩色光传播。告示牌文字写入存档，预览未完整显示；容器内部为空，座位与部分物件不提供额外玩法。</p><p class="small">NBT SHA-256：'+sp['source_nbt_sha256']+'</p></details></section><footer>木漏日町 / Komorebi09 · '+run+' · HAF 0.4<br>18 栋有界原创街区试验。源工程与历史过程另附。</footer></main><dialog id="viewer"><img id="viewer-img" alt="放大预览"><button id="viewer-close">关闭</button></dialog>')
js='''const images=IMAGES;const buildings=BUILDINGS;let current='B01',mode='front';const $=id=>document.getElementById(id);const extra=b=>b.floors===2?'upper':'detail';function show(id,key){$(id).src=images[key];$(id).dataset.img=key;}function choose(id){current=id;const b=buildings.find(x=>x.id===id);$('building-id').textContent=b.id;$('building-title').textContent=b.name;$('building-info').textContent=b.floors+' 层 · '+({'machiya':'大町屋 / 店住一体','compact':'紧凑两层 / 起居与用途空间','single':'单层 / 专门用途空间'}[b.family])+'。'+b.use_points.length+' 个接近点已作离线检查。';let [x,y,z]=b.entry;let dz=b.rotation===180?-3:3;$('tp-command').textContent='/tp @s '+(x-82)+' '+(y+62)+' '+(z-56+dz)+' '+(b.rotation===180?0:180)+' 0';document.querySelectorAll('[data-building]').forEach(e=>e.classList.toggle('active',e.dataset.building===id));renderBuilding();}function renderBuilding(){const b=buildings.find(x=>x.id===current),part=mode==='extra'?extra(b):mode,key=current+'_'+part;show('building-img',key);$('building-caption').textContent=current+' · '+b.name+' · '+({'front':'临街门面','inside':'首层室内','upper':'二层起居','detail':'室内细部','plan':'首层平面'}[part]);$('download-view').href=images[key];$('download-view').download=key+'.webp';document.querySelectorAll('#building-views button').forEach(e=>e.classList.toggle('active',e.dataset.mode===mode));}document.addEventListener('click',e=>{const b=e.target.closest('[data-building]');if(b){choose(b.dataset.building);return;}const im=e.target.closest('img.zoom');if(im){$('viewer-img').src=images[im.dataset.img];$('viewer').showModal();}});$('site-map').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const b=e.target.closest('[data-building]');if(b){e.preventDefault();choose(b.dataset.building);}}});$('building-views').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(b){mode=b.dataset.mode;renderBuilding();}});$('building-filter').addEventListener('change',e=>{document.querySelectorAll('#building-list button').forEach(b=>b.hidden=e.target.value!=='all'&&b.dataset.family!==e.target.value);});$('hero-controls').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(!b)return;show('hero-img',b.dataset.view);$('hero-caption').textContent=b.textContent;document.querySelectorAll('#hero-controls button').forEach(x=>x.classList.toggle('active',x===b));});$('viewer-close').addEventListener('click',()=>$('viewer').close());choose('B01');'''
js=js.replace('IMAGES','Object.assign(Object.fromEntries(Array.from(document.querySelectorAll("img[data-img]")).map(e=>[e.dataset.img,e.src])), '+json.dumps({k:v for k,v in images.items()if k not in used})+')').replace('BUILDINGS',json.dumps(sp['buildings'],ensure_ascii=False));p.append('<script>'+js+'</script></body></html>');OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(''.join(p));print(json.dumps({'html':str(OUT),'bytes':OUT.stat().st_size,'views':len(records)}))
